import {getTerminalMonitoringList} from "@/api/terminal";
import moment from "moment";
export default {
  data() {
    return {
      // 搜索相关
      searchForm: {
        ip: undefined,
        status: undefined,
        current: 1,
        size: 20,
      },
      // 表格相关
      dataList: [],
      loading: false,
      tableHeight: undefined,
      total: 0,
    };
  },
  components: {moment},
  mounted(){
    // 设置页面元素高度
    this.setPageContentHeight()
    // 设置表格高度
    this.setTableHeight()
    //加载数据
    this.onLoad();
  },
  methods: {
    // 设置表格高度
    setTableHeight() {
      let pageBody = document.getElementsByClassName('page_body')
      this.tableHeight = pageBody[0].offsetHeight - 61 - 47 + 'px'
    },
    handleQuery() {
      this.searchForm.current = 1
      this.onLoad();
    },
    searchReset() {
      //重置按钮
      this.searchForm = {
        ip: undefined,
        status: undefined,
        current: 1,
        size: 20,
      }
      this.onLoad();
    },
    onLoad() {
      //加载数据
      this.loading = true;
      getTerminalMonitoringList(this.searchForm).then(res => {
        const data = res.data;
        this.total = data.total;
        this.dataList = data.records.map(item=> {
          return {
            ...item,
            openTime: moment(item.openTime).format("YYYY-MM-DD HH:mm:ss"),
            showdownTime: moment(item.showdownTime).format("YYYY-MM-DD HH:mm:ss"),
          }
        });
        this.loading = false;
      });
    },
  }
};
